def link_existing_instruments(apps, schema_editor):
    """Instruments built from an order before this link only kept the order id in their configuration :
    find their order line (same snapshot, else same product name) and link it."""
    Instrument = apps.get_model("haeron_guitar_api", "Instrument")
    OrderItem = apps.get_model("haeron_guitar_api", "OrderItem")
    for instrument in Instrument.objects.filter(order_item__isnull=True, configuration__source="order"):
        configuration = instrument.configuration or {}
        try:
            items = list(OrderItem.objects.filter(order__uuid=configuration.get("orderId")).order_by("pk"))
        except (ValueError, ValidationError):  # not an order id : left unlinked
            continue
        item = next((i for i in items if i.config_snapshot == configuration.get("snapshot")), None) or next(
            (i for i in items if i.product_name == configuration.get("product")), None
        )
        if item is not None:
            instrument.order_item = item
            instrument.save(update_fields=["order_item"])


